  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the jets allocated to training in a given year drawn from that same year's production, or can jets produced in earlier years be carried over and used for training in later years?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding the source of jets for training (current year production vs. carryover)."
}

